from pathlib import Path
import json,re,hashlib,datetime,collections
B=Path('/home/popac/alekpopovic.github.io/books/inside-orch'); S=B/'evidence/orch'
lock=json.loads((B/'evidence/source-lock.json').read_text()); SHA=lock['baseline_sha']; base='https://github.com/alekpopovic/orch/blob/'+SHA+'/'
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
def write(path,data):
 p=B/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(data,indent=2)+'\n' if isinstance(data,(dict,list)) else data)
def ref(path,start=1,end=None):
 assert (S/path).is_file(),path
 lines=(S/path).read_text().splitlines();end=end or start;assert 0<start<=end<=len(lines),(path,start,end,len(lines))
 return {'path':path,'start_line':start,'end_line':end,'url':base+path+f'#L{start}'+(f'-L{end}' if end!=start else '')}
def at(path,needle,n=0):
 ls=(S/path).read_text().splitlines();found=[i+1 for i,l in enumerate(ls) if needle in l];assert found,(path,needle);return ref(path,found[n])
def link(r):return '['+r['path']+':'+str(r['start_line'])+']('+r['url']+')'
def sym(path):
 result=[]
 for i,l in enumerate((S/path).read_text().splitlines(),1):
  if re.match(r'^(func |type \w+ (?:interface|struct)|const \()',l):result.append({'declaration':l,'line':i,'url':base+path+f'#L{i}'})
 return result
files=[];tests=[];interfaces=[]
for f in sorted(S.rglob('*.go')):
 p=f.relative_to(S).as_posix();text=f.read_text();entry={'path':p,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'symbols':sym(p)};files.append(entry)
 for i,l in enumerate(text.splitlines(),1):
  if re.match(r'^type \w+ interface',l):interfaces.append({'path':p,'line':i,'declaration':l,'url':base+p+f'#L{i}'})
 if p.endswith('_test.go'):
  prereqs=[{'line':i,'text':l.strip()} for i,l in enumerate(text.splitlines(),1) if any(x in l for x in ['t.Skip','os.Getenv','go:build','DROP SCHEMA','TRUNCATE','CREATE SCHEMA'])]
  tests.append({'path':p,'test_names':re.findall(r'^func ((?:Test|Fuzz|Benchmark)\w+)\(',text,re.M),'prerequisite_and_isolation_lines':prereqs,'scope':'source inspected; not executed by inventory'})
