migrations=[]
for f in sorted((S/'migrations').glob('*.up.sql')):
 p=f.relative_to(S).as_posix();down=p.replace('.up.sql','.down.sql');assert (S/down).exists()
 statements=[{'line':i,'statement':l.strip()} for i,l in enumerate(f.read_text().splitlines(),1) if re.search(r'\b(?:CREATE TABLE|ALTER TABLE|DROP TABLE|CREATE .*INDEX|REFERENCES)\b',l,re.I)]
 tables=sorted(set(re.findall(r'(?:CREATE TABLE(?: IF NOT EXISTS)?|ALTER TABLE(?: IF EXISTS)?|REFERENCES)\s+([a-z_]+)',f.read_text(),re.I)))
 migrations.append({'id':f.name[:6],'up':p,'down':down,'touched_tables':tables,'statements':statements,'scope':'SQL source inspected; execution requires disposable PostgreSQL'})
routes=[]
for f in sorted((S/'internal/api').glob('*.go')):
 if f.name.endswith('_test.go'):continue
 for i,l in enumerate(f.read_text().splitlines(),1):
  for route in re.findall(r'mux\.Handle(?:Func)?\("([^"]+)"',l):routes.append({'method_path':route,'source':ref(f.relative_to(S).as_posix(),i)})
